---@class CMonsterPkHandler : CPacketHandlers
local MonsterPkHandler = T(Global, "PacketHandlers")
---@type CActorNpcFactory
local ActorNpcFactory = T(Global, "ActorNpcFactory")
---@type RewardConfig
local RewardConfig = T(Global, "RewardConfig")

function MonsterPkHandler:createBossRewardChest(packet)
    ActorNpcFactory:createActorNpc("g1048_chest.actor", packet.position, self:getYaw() - 180, function(actorNpc)
        actorNpc.entity:setSkillName("idle")
        actorNpc:setEntityInterface(Define.ActorNpcInterface.BossRewardChest)
        actorNpc:callFunction("onInterfaceCreate", packet.recordId, packet.monsterId, packet.rank)
    end)
end

function MonsterPkHandler:onGetMonsterExp(packet)
    ---@type CEntityMonster
    local monster = EntityCache:getEntityByServerId(packet.entityId)
    if not monster then
        return
    end
    if monster.__cname ~= "EntityMonster" then
        return
    end
    monster:onShowExp()
end

function MonsterPkHandler:onMonsterRewardTip(packet)
    local params = {}
    if packet.name then
        table.insert(params, packet.name)
    end
    if packet.itemId then
        table.insert(params, Lang:getItemName(packet.itemId or 0, 0))
    end
    if packet.rewardId then
        table.insert(params, RewardConfig:getRewardName(packet.rewardId))
    end
    local tip = Lang:getString(packet.tip)
    for i, param in pairs(params) do
        tip = string.gsub(tip, "{" .. i .. "}", param)
    end
    MsgSender.sendTopTips(5, tip)
end

return MonsterPkHandler